def icon(name):
 return f'<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="{PATHS[name]}"/></svg>'
def photo(n,alt,cls='',eager=False):
 return f'<img src="assets/images/IMG_{n}.JPG.jpeg" alt="{escape(alt)}" width="1440" height="960" loading="{"eager" if eager else "lazy"}" decoding="async" {"fetchpriority=high" if eager else ""} class="{cls}">'
