def hero(lines,n,alt,subtitle,description='',eyebrow='WELCOME TO GRAND TECHNO',home=False,compact=False,buttons=None):
 title=' '.join(lines)
 actions=buttons if buttons is not None else btn('Make a Reservation','contact.html#inquiry')
 actions=actions.replace('btn-outline','btn-light')
