 home_actions=f'<div class="actions">{actions}</div>' if home else ''
 return f'''<section class="hero page-banner {'home-hero' if home else ''}">{photo(n,alt,'hero-image',True)}<div class="container hero-content">{home_details}<h1><span class="title-line"><span>{title}</span></span></h1><p class="hero-subtitle">{subtitle}</p>{home_actions}</div></section>'''

